/** Local authenticated regression runner. Session is generated by the WP-CLI fixture. */
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const { createRequire } = require('node:module');
const engineRequire = createRequire(path.join(process.env.MRN_QA_ENGINE_ROOT, 'package.json'));
const { chromium } = engineRequire('playwright');
const AxeBuilder = engineRequire('@axe-core/playwright').default;
const [stage, sessionPath, outputDir] = process.argv.slice(2);
const session = JSON.parse(fs.readFileSync(sessionPath, 'utf8'));
assert(new URL(session.base_url).hostname.endsWith('.localhost'), 'local runtimes only');
fs.mkdirSync(outputDir, { recursive: true });
const handles = ['mrn-base-stack-admin-repeater-controls', 'mrn-shared-icon-chooser', 'mrn-shared-icon-chooser-fontawesome', 'mrn-base-stack-admin-icon-choosers', 'mrn-config-helper-acf-layout-picker', 'mrn-acf-char-count'];
const report = { stage, baseUrl: session.base_url, postId: session.post_id, pages: {}, interactions: [] };
const normalize = value => String(value).replace(/row-[a-z0-9]+/g, 'row-*').replace(/post=\d+/g, 'post=FIXTURE');
function assertTest(value, label) { assert(value, label); report.interactions.push(label); }
async function snapshot(page, label, issues) {
 const assets = await page.evaluate((prefixes) => {
  const nodes = [...document.querySelectorAll('script[id],link[id]')].filter(n => prefixes.some(p => n.id === p + '-js' || n.id === p + '-js-extra' || n.id === p + '-css'));
  const nav = performance.getEntriesByType('navigation')[0];
  return { fields: document.querySelectorAll('.acf-field').length, assets: nodes.map(n => ({id:n.id,inlineChars:n.tagName==='SCRIPT'&&!n.src?n.textContent.length:0,url:n.src||n.href||''})), scripts:document.querySelectorAll('script[src]').length, styles:document.querySelectorAll('link[rel="stylesheet"]').length, navigation:nav?{ttfb:nav.responseStart-nav.startTime,domContentLoaded:nav.domContentLoadedEventEnd-nav.startTime}:null };
 }, handles);
 const axe = await new AxeBuilder({page}).withTags(['wcag2a','wcag2aa','wcag21a','wcag21aa']).analyze();
 const violations = axe.violations.flatMap(v=>v.nodes.map(n=>({id:v.id,impact:v.impact,target:n.target.map(normalize).join(' ')})));
 report.pages[label] = {...assets,issues:JSON.parse(JSON.stringify(issues)),axe:violations};
 fs.writeFileSync(path.join(outputDir,stage+'.json'),JSON.stringify(report,null,2));
 console.log(JSON.stringify({stage,page:label,helperAssets:assets.assets.length,acfFields:assets.fields,axeNodes:violations.length,consoleErrors:issues.console.length}));
 await page.screenshot({path:path.join(outputDir,stage+'-'+label+'.png'),fullPage:false});
}
(async()=>{
 const browser = await chromium.launch({headless:true});
 const context = await browser.newContext({ignoreHTTPSErrors:true,viewport:{width:1440,height:1100}});
 await context.addCookies(session.cookies);
 const page = await context.newPage();
 page.setDefaultTimeout(20000);
 const issues={console:[],page:[],failedAssets:[]};
 page.on('console',msg=>{if(msg.type()==='error')issues.console.push(normalize(msg.text()));});
 page.on('pageerror',error=>issues.page.push(normalize(error.message)));
 page.on('response',response=>{if(response.status()>=400&&/\.(?:js|css)(?:\?|$)/.test(response.url()))issues.failedAssets.push({url:new URL(response.url()).pathname,status:response.status()});});
 async function visit(url) {
  issues.console=[];issues.page=[];issues.failedAssets=[];
  const response=await page.goto(session.base_url+url,{waitUntil:'domcontentloaded',timeout:90000});
  assert(response.status()<400,'HTTP success for '+url);
  await page.waitForLoadState('load',{timeout:90000});
  assert(!/wp-login|site-login/.test(page.url()),'authenticated admin session');
  await page.locator('#wpbody-content').waitFor();
 }
 try {
  async function settingsCheck() {
   await visit('/wp-admin/options-general.php?page=mrn-config-helper');
   await snapshot(page,'config-settings',issues);
   assertTest(report.pages['config-settings'].assets.some(a=>a.id==='mrn-shared-icon-chooser-js'),'settings icon consumer retains shared chooser');
  }
  if (process.env.MRN_QA_SETTINGS_ONLY === '1') {
   const prior = JSON.parse(fs.readFileSync(path.join(outputDir,stage+'.json'),'utf8'));
   Object.assign(report,prior);
   await settingsCheck();
   return;
  }
  const listCases = [['empty-acf','/wp-admin/tools.php?page=mrn-admin-field-assets-qa-empty'],['pages','/wp-admin/edit.php?post_type=page'],['posts','/wp-admin/edit.php'],['site-health','/wp-admin/site-health.php'],['reading-settings','/wp-admin/options-reading.php']];
  if (process.env.MRN_QA_EDITOR_ONLY === '1' && fs.existsSync(path.join(outputDir,stage+'.json'))) {
   const prior = JSON.parse(fs.readFileSync(path.join(outputDir,stage+'.json'),'utf8'));
   for (const [label] of listCases) if (prior.pages[label]) report.pages[label] = prior.pages[label];
  }
  for(const [label,url] of process.env.MRN_QA_EDITOR_ONLY === '1' ? [] : listCases) {
   await visit(url);await snapshot(page,label,issues);
   if(stage!=='baseline')assertTest(report.pages[label].assets.length===0,label+' has no scoped field helper assets');
  }
  await visit('/wp-admin/post.php?post='+session.post_id+'&action=edit');
  await page.locator('[data-key="field_mrnqa_summary"] input[type="text"]').waitFor({state:'visible'});
  await snapshot(page,'editor-initial',issues);
  fs.writeFileSync(path.join(outputDir,stage+'-editor-dom.json'),JSON.stringify(await page.locator('#acf-group_mrn_asset_qa').evaluate(el=>({html:el.outerHTML})),null,2));
  const field=key=>page.locator('.acf-field[data-key="'+key+'"]');
  const counter=key=>field(key).locator('.mrn-acf-char-count').first();
  await field('field_mrnqa_summary').locator('input[type="text"]').fill('Local QA copy');
  await page.waitForFunction(()=>document.querySelector('[data-key="field_mrnqa_summary"] .mrn-acf-char-count')?.textContent.includes('13 / 30'));
  assertTest(true,'configured field counter updates');
  await field('field_mrnqa_rows').locator('a[data-event="add-row"]').last().click();
  const row=field('field_mrnqa_rows').locator('.acf-row:not(.acf-clone)').last();
  await row.locator('[data-key="field_mrnqa_row_copy"] input[type="text"]').fill('Dynamic row');
  await page.waitForFunction(()=>[...document.querySelectorAll('[data-key="field_mrnqa_row_copy"] .mrn-acf-char-count')].some(n=>n.textContent.includes('11 / 30')));
  assertTest(true,'new repeater row retains counter');
  const collapse = field('field_mrnqa_rows').getByRole('button',{name:'Collapse All',exact:true});
  if (await collapse.count()) {
   await collapse.press('Enter');
   assertTest(await row.locator('input[type="text"]').isHidden(),'repeater collapse keyboard action');
   await field('field_mrnqa_rows').getByRole('button',{name:'Expand All',exact:true}).press('Enter');
   assertTest(await row.locator('input[type="text"]').isVisible(),'repeater expand keyboard action');
  } else {
   report.interactions.push('Existing disabled bulk repeater controls remain disabled');
  }
  await field('field_mrnqa_sections').locator('a[data-name="add-layout"][data-context="bottom-actions"]').click();
  await page.locator('.mrn-acf-layout-picker__card').filter({hasText:'QA Copy'}).press('Enter');
  await field('field_mrnqa_sections').locator('.values [data-key="field_mrnqa_section_copy"] input[type="text"]').last().fill('Dynamic layout');
  await page.waitForFunction(()=>[...document.querySelectorAll('[data-key="field_mrnqa_section_copy"] .mrn-acf-char-count')].some(n=>n.textContent.includes('14 / 30')));
  assertTest(true,'layout picker inserts a field with working counter');
  const clone=page.locator('.acf-field[data-name="qa_clone_qa_prototype"]');
  await clone.locator('input[type="text"]').fill('Cloned copy');
  assertTest((await clone.locator('.mrn-acf-char-count').innerText()).includes('11 / 30'),'cloned field counter updates');
  await field('field_mrnqa_icons').getByRole('button',{name:'Choose Icon',exact:true}).click();
  await page.locator('.mrn-shared-icon-modal').waitFor({state:'visible'});
  await snapshot(page,'icon-dialog',issues);
  await page.locator('.mrn-shared-icon-grid__item[data-value="dashicons-heart"]').press('Enter');
  assertTest(await page.locator('.mrn-shared-icon-modal').isHidden(),'icon can be selected by keyboard');
  assertTest((await field('field_mrnqa_icon_dashicons').locator('input[type="text"]').inputValue())==='dashicons-heart','icon selection updates ACF value');
  await page.locator('#page_template').selectOption('page-sidebar-left.php');
  await field('field_mrnqa_late_copy').locator('input[type="text"]').waitFor({state:'visible'});
  await field('field_mrnqa_late_copy').locator('input[type="text"]').fill('AJAX field');
  await page.waitForFunction(()=>document.querySelector('[data-key="field_mrnqa_late_copy"] .mrn-acf-char-count')?.textContent.includes('10 / 30'));
  assertTest(true,'AJAX-added field group retains counter');
  await snapshot(page,'editor-after-interactions',issues);
  await Promise.all([
   page.waitForNavigation({waitUntil:'domcontentloaded',timeout:90000}),
   page.locator('#save-post').click()
  ]);
  await page.waitForFunction(()=>document.querySelector('#message')?.textContent.match(/updated|saved|submitted/i),null,{timeout:30000});
  assertTest((await field('field_mrnqa_summary').locator('input[type="text"]').inputValue())==='Local QA copy','fixture values survive save/reload');
  await snapshot(page,'editor-saved',issues);
  await settingsCheck();
 } catch(error) {
  report.failure=error.stack;
  await page.screenshot({path:path.join(outputDir,stage+'-failure.png'),fullPage:false}).catch(()=>{});
  fs.writeFileSync(path.join(outputDir,stage+'-failure-dom.html'),await page.content());
  process.exitCode=1;
 } finally {
  fs.writeFileSync(path.join(outputDir,stage+'.json'),JSON.stringify(report,null,2));
  console.log(JSON.stringify({stage,pages:Object.fromEntries(Object.entries(report.pages).map(([k,v])=>[k,{assets:v.assets.map(a=>a.id),fields:v.fields,axe:v.axe.length,console:v.issues.console.length}])),interactions:report.interactions,failure:report.failure?.split('\n')[0]},null,2));
  await browser.close();
 }
})();
